declare loc uuid;seed jsonb:=$MENU_DATA${"profile": {"title": "JusTini’s Restaurant & Menu", "description": "JusTini’s · 3162 Dauphine Street · New Orleans, LA. Explore brunch, small plates, entrées, desserts, cocktails, happy hour, and catering. All dishes are made to order with fresh, quality ingredients. Sit back, sip your cocktail, and enjoy the vibes.", "notes": "Printed menu notes: all shrimp and crawfish are imported for quality and flavor. 18% gratuity included on all checks. 90-minute seating limit per table. A $30 cake fee applies to outside desserts.\n\nHappy hour, as printed: Tuesday 4–6 PM; Wednesday all day 12–9 PM; Thursday 3–6 PM; Friday 3–7 PM; Saturday 5–7 PM. Discounts on selected liquor. Minimum of three happy-hour tacos per order.\n\nBottomless brunch cocktails: $25 for 90 minutes; available every Saturday with a brunch entrée purchase, as printed. Confirm availability and current service policies with management.\n\nCatering: half pans serve up to 20 guests; full pans serve up to 40, except items with an explicit count. The sales calculator uses listed menu prices before tax and gratuity. Menu descriptions do not replace recipes or allergen checks."}, "items": [{"source_key": "menu-20261024:brunch-runch-entr-es-alvar-st-avocado-toast", "name": "Alvar St. Avocado Toast", "description": "Texas toast, perfectly toasted, topped with creamy avocado, a hint of lemon, sea salt, and crushed red peppers. Fresh heirloom tomatoes and a drizzle of extra virgin olive oil complete this refreshing, light bar fare.", "category": "Brunch entrées", "service": "brunch", "notes": "Add egg $2.", "prices": [{"label": "Avocado toast", "cents": 1300, "unit": "order", "minimum": 1}, {"label": "With egg", "cents": 1500, "unit": "order", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-dauphine-louisa-chicken-and-french-toast", "name": "Dauphine & Louisa Chicken and French Toast", "description": "Buttery French toast topped with fresh strawberries and blueberries; served with two crispy fried chicken wings dipped in honey buffalo sauce.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 2000, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-bywater-breakfast-skillet", "name": "Bywater Breakfast Skillet", "description": "Creamy Southern-style grits, two fried eggs, shredded cheddar, roasted corn, heirloom tomatoes, grilled jalapeños, and bacon crumble. A flavorful dish to satisfy your cravings and fuel you for the day ahead.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 2100, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-lamanche-st-lamb-chops", "name": "Lamanche St. Lamb Chops", "description": "Grilled lamb lollipops, creamy grits, and roasted asparagus. Marinated with herbs and spices, the lamb is grilled with a charred exterior and juicy interior, topped with grilled onions and bell peppers. Velvety, slow-cooked grits add Southern comfort.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 4000, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-poland-ave-hot-sausage-croissant", "name": "Poland Ave Hot Sausage Croissant", "description": "A bold New Orleans hot sausage patty packed with Cajun spices, paired with fluffy scrambled eggs, melted cheese, fresh spinach, and tomato inside a buttery croissant. Served with crispy breakfast potatoes.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1700, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-catfish-dauphine-grits", "name": "Catfish Dauphine & Grits", "description": "A tender, flaky catfish fillet topped with a garlicky cream sauce spiced just right. Served over vibrant mixed greens, heirloom tomatoes, blackened shrimp, and grits for a contrast of textures and flavors.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 2200, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-rampart-st-ribeye-eggs", "name": "Rampart St. Ribeye & Eggs", "description": "A juicy 12 oz ribeye cooked to your preferred temperature, charred to perfection. Served with your choice of eggs—scrambled, sunny-side up, or fried—and crispy, seasoned breakfast potatoes.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 3500, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-n-roman-redfish-grits", "name": "N. Roman Redfish & Grits", "description": "Blackened redfish served over creamy grits, with corn maque choux topped with crawfish tails.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 3800, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-charbonnet-st-crawfish-grits", "name": "Charbonnet St. Crawfish & Grits", "description": "Creamy grits smothered in rich crawfish sauce, loaded with tender crawfish tails and served with a slice of Texas toast.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 2500, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-justini-s-classic-breakfast", "name": "JusTini’s Classic Breakfast", "description": "Two fluffy scrambled eggs, creamy Southern-style grits, your choice of crispy bacon or a hot sausage patty, and a thick slice of buttery Texas toast.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1500, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-runch-entr-es-traditional-burger-fries", "name": "Traditional Burger & Fries", "description": "A juicy beef patty served on a buttery bun dressed with American cheese, fresh red onion, lettuce, tomato, and pickles. Served with crispy seasoned French fries.", "category": "Brunch entrées", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1600, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6434.jpeg"}, {"source_key": "menu-20261024:brunch-esseps-t-runch-acos-bacon-egg-cheese-tacos", "name": "Bacon, Egg & Cheese Tacos", "description": "Crispy bacon crumbles, scrambled eggs, and shredded cheese stuffed in three flour tortillas topped with fresh jalapeños.", "category": "Lesseps St. Brunch Tacos", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1400, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-esseps-t-runch-acos-hot-sausage-egg-cheese-tacos", "name": "Hot Sausage, Egg & Cheese Tacos", "description": "New Orleans hot sausage, scrambled eggs, and shredded cheese stuffed in three flour tortillas topped with tomatoes.", "category": "Lesseps St. Brunch Tacos", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1400, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-esseps-t-runch-acos-veggie-tacos", "name": "Veggie Tacos", "description": "Fresh bell peppers and onions, sliced and grilled, served in three flour tortillas topped with white corn and tomatoes, garnished with diced onions and cilantro.", "category": "Lesseps St. Brunch Tacos", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1400, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-esseps-t-runch-acos-steak-egg-cheese-tacos", "name": "Steak, Egg & Cheese Tacos", "description": "8 oz ribeye, sliced, scrambled eggs, and shredded cheese stuffed in three flour tortillas topped with fresh grilled peppers and onions.", "category": "Lesseps St. Brunch Tacos", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1800, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-runch-cocktails-mimosa", "name": "Mimosa", "description": "Crisp sparkling wine and your choice of orange, pineapple, or cranberry juice. Light, bubbly, and refreshing, with fruit and effervescence.", "category": "Brunch cocktails", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1000, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-runch-cocktails-bloody-justini", "name": "Bloody JusTini", "description": "Tito’s vodka, house-seasoned tomato mix, lemon juice, and a blend of bold spices. Made as mild or as spicy as you like and garnished with olives, spicy green beans, and pickled okra.", "category": "Brunch cocktails", "service": "brunch", "notes": "Add a grilled shrimp skewer for $5.", "prices": [{"label": "Bloody JusTini", "cents": 1300, "unit": "cocktail", "minimum": 1}, {"label": "With grilled shrimp skewer", "cents": 1800, "unit": "cocktail", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-runch-cocktails-brunch-lychee-spritz", "name": "Brunch Lychee Spritz", "description": "Camarena Reposado, brut champagne, and JusTini’s lychee syrup.", "category": "Brunch cocktails", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1500, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-runch-cocktails-it-s-shirley-sangria", "name": "It’s Shirley Sangria", "description": "A refreshing tequila-based white sangria featuring peach flavors, white cranberry juice, and elderflower notes.", "category": "Brunch cocktails", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1400, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-runch-cocktails-matcha-latte-tini", "name": "Matcha-Latte Tini", "description": "A blend of vanilla vodka, JusTini’s matcha syrup, and Irish cream. “Adding a little liquor to a matcha latte never hurt nobody!”", "category": "Brunch cocktails", "service": "brunch", "notes": "", "prices": [{"label": "Menu price", "cents": 1500, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:brunch-runch-cocktails-bottomless-brunch-cocktails", "name": "Bottomless Brunch Cocktails", "description": "90 minutes of Classic Mimosas, Sparkling Lemon Drops, and It’s Shirley Sangria. Available every Saturday with the purchase of a brunch entrée.", "category": "Brunch cocktails", "service": "brunch", "notes": "Saturday only and brunch entrée purchase required, as printed. Confirm current service rules before offering.", "prices": [{"label": "Menu price", "cents": 2500, "unit": "item", "minimum": 1}], "available": true, "recommend": false, "source_file": "IMG_6435.jpeg"}, {"source_key": "menu-20261024:regular-ntr-es-catfish-dauphine", "name": "Catfish Dauphine", "description": "Tender, flaky catfish fillet topped with a rich, garlicky cream sauce. Served over seafood rice with mixed greens, heirloom tomatoes, and blackened shrimp for a contrast of textures and flavors.", "category": "Entrées", "service": "regular", "notes": "", "prices": [{"label": "Menu price", "cents": 2200, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_2430_1.jpeg"}, {"source_key": "menu-20261024:regular-ntr-es-gallier-st-ginger-soy-salmon", "name": "Gallier St. Ginger Soy Salmon", "description": "A perfectly grilled salmon fillet topped with fresh mango pico and glazed with ginger soy, served over seafood rice and crispy mixed greens.", "category": "Entrées", "service": "regular", "notes": "", "prices": [{"label": "Menu price", "cents": 2800, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_2430_1.jpeg"}, {"source_key": "menu-20261024:regular-ntr-es-piety-street-blackened-shrimp-salad", "name": "Piety Street Blackened Shrimp Salad", "description": "Crisp mixed greens topped with blackened grilled shrimp, creamy feta, shredded carrots, red onions, cucumbers, heirloom tomatoes, and walnuts, served with Sweet Onion Vidalia dressing.", "category": "Entrées", "service": "regular", "notes": "", "prices": [{"label": "Menu price", "cents": 1800, "unit": "item", "minimum": 1}], "available": true, "recommend": true, "source_file": "IMG_2430_1.jpeg"}, {"source_key": "menu-20261024:regular-ntr-es-chartres-st-blackened-salmon-caesar-salad", "name": "Chartres St. Blackened Salmon Caesar Salad", "description": "Fresh romaine lettuce topped with blackened salmon, crispy croutons, Parmesan cheese, and house Caesar dressing.", "categor