 for loc in select id from public.locations where regexp_replace(lower(name),'[^a-z0-9]','','g') in ('justinisneworleans','justinisnola','justinis') loop
  n:=n+1;
  insert into public.restaurant_menu_profiles(location_id,data) values(loc,seed->'profile') on conflict(location_id) do nothing;
  for item in select value from jsonb_array_elements(seed->'items') loop
   if not menu_catalog_private.valid_item(item-'source_key') then raise exception 'Invalid menu seed: %',item->>'name';end if;
   insert into public.restaurant_menu_items(location_id,source_key,data) values(loc,item->>'source_key',item-'source_key') on conflict(location_id,source_key) do nothing;
  end loop;
  insert into public.preshift_preset_chunks(location_id,title,category,weekday,body,source_key,visibility) values(loc,'Selling with intention — reusable scripts','sales',null,$COACHING$SELL WITH INTENTION

Welcome & first drink: “Are you in the mood for something refreshing or something liquor-forward? I can recommend a cocktail.”

Offer a starter while guests decide: “Would you like to start with an appetizer for the table while you look over the menu?” Use an available menu item and its current description.

The next round: “Would you like another of the same, or would you like me to recommend something different?”

Dessert before the check: “Would you like to finish with dessert? I can walk you through today’s options.”

Use the live menu for current prices and availability. Recommend items that fit the guest and the stage of the meal. Review updated menu prices before publishing a pre-shift.$COACHING$,'home-selling-coaching-20261024','shared') on conflict(location_id,source_key) do nothing;
 end loop;
 if n=0 then raise exception 'No matching JusTini’s location found. No menu rows were imported. Verify the location name before changing the seed selector.';end if;
end $seed$;
